from dataclasses import dataclass, field
# Define your classes and UpdatePosition function here

@dataclass
class OrderedPair:
    x: float = 0.0
    y: float = 0.0

@dataclass
class Body:
    name: str = ""
    position: OrderedPair = field(default_factory=OrderedPair)
    velocity: OrderedPair = field(default_factory=OrderedPair)
    acceleration: OrderedPair = field(default_factory=OrderedPair)


# Write your update_position() function here
def update_position(b: Body, old_acceleration: OrderedPair, old_velocity: OrderedPair, time: float) -> OrderedPair:
    new_P = OrderedPair(
    b.position.x + old_velocity.x * time + 0.5*old_acceleration.x*(time)**2,
    b.position.y + old_velocity.y * time + 0.5*old_acceleration.y*(time)**2   
    )
    return new_P

from dataclasses import dataclass, field
# Define your classes and UpdatePosition function here

@dataclass
class OrderedPair:
    x: float = 0.0
    y: float = 0.0

@dataclass
class Body:
    name: str = ""
    position: OrderedPair = field(default_factory=OrderedPair)
    velocity: OrderedPair = field(default_factory=OrderedPair)
    acceleration: OrderedPair = field(default_factory=OrderedPair)


def update_velocity(b: Body, old_acceleration: OrderedPair, time: float) -> OrderedPair:
    new_V = (
        b.velocity.x + 0.5 * (old_acceleration.x + b.acceleration.x) * time,
        b.velocity.y + 0.5 * (old_acceleration.y + b.acceleration.y) * time
    )
    return new_V

import math
from datatypes import Universe, Body, OrderedPair

# Simulation Code

def simulate_gravity(initial_universe: Universe, num_gens: int, time: int) -> list[Universe]:
    initial_universe = copy_universe(initial_universe)
    for b in initial_universe.bodies:
        b.acceleration = update_acceleration(initial_universe, b)
    time_points: list[Universe] = [initial_universe]

    for i in range(1, num_gens+1):
        prev_universe = time_points[i-1]
        next_universe = update_universe(prev_universe, time)
        time_points.append(next_universe)

    return time_points


def update_universe(current_universe: Universe, time: float) -> Universe:
    """Uses a velocity-Verlet style update: compute new positions from the
    current state, then advance acceleration and velocity accordingly."""
    new_universe = copy_universe(current_universe) #because universe is mutable, create a deep copy

    for body in new_universe.bodies:
        body.position = update_position(body, body.acceleration, body.velocity, time)
    for b in new_universe.bodies:
        old_accel = b.acceleration
        b.acceleration = update_acceleration(new_universe, b)
        b.velocity = update_velocity(b, old_accel, time)

    return new_universe


def update_acceleration(current_universe: Universe, b: Body) -> OrderedPair:
    net_force = compute_net_force(current_universe, b)
    ax = net_force.x / b.mass
    ay = net_force.y / b.mass

    return OrderedPair(ax, ay)


def update_velocity(b: Body, old_acceleration: OrderedPair, time: float) -> OrderedPair:
    vx = b.velocity.x + 0.5*(b.acceleration.x + old_acceleration.x) * time
    vy = b.velocity.y + 0.5*(b.acceleration.y + old_acceleration.y) * time
    return OrderedPair(vx, vy)


def update_position(b: Body, old_acc: OrderedPair, old_vel: OrderedPair, time: float) -> OrderedPair:
    px = b.position.x + old_vel.x*time + 0.5*old_acc.x*time**2
    py = b.position.y + old_vel.y*time + 0.5*old_acc.y*time**2
    return OrderedPair(px, py)

def compute_net_force(current_universe: Universe, b: Body) -> OrderedPair:
    net_force = OrderedPair(0.0,0.0)

    for object in current_universe.bodies:
        if object is not b:
            force = compute_force(b, object, current_universe.gravitational_constant)
            net_force.x += force.x
            net_force.y += force.y

    return net_force


def compute_force(b1: Body, b2: Body, G: float) -> OrderedPair:
    # = G(m1)(m2) / (d**2)
    d = distance(b1.position, b2.position)
    if d == 0.0: return OrderedPair(0.0,0.0)
    F_magnitude = (G * b1.mass * b2.mass) / d**2

    dx = b2.position.x - b1.position.x
    dy = b2.position.y - b1.position.y
    Fx = F_magnitude * (dx/d)
    Fy = F_magnitude * (dy/d)

    return OrderedPair(Fx, Fy)




def distance(p1: OrderedPair, p2: OrderedPair) -> float:
    x_part = (p2.x - p1.x) ** 2
    y_part = (p2.y - p1.y) ** 2
    return (x_part + y_part) ** 0.5


def copy_universe(current_universe: Universe) -> Universe:
    new_bodies: list[Body] = []
    for body in current_universe.bodies:
        new_bodies.append(copy_body(body))

    u = Universe(
        new_bodies, current_universe.width, current_universe.gravitational_constant
    )

    return u


def copy_body(b: Body) -> Body:
    return Body(
      name = b.name,
      mass = b.mass,
      position = OrderedPair(b.position.x, b.position.y),
      velocity = OrderedPair(b.velocity.x, b.velocity.y),
      acceleration = OrderedPair(b.acceleration.x, b.acceleration.y),
      radius = b.radius,
      red = b.red,
      green = b.green,
      blue = b.blue
)

